'use strict';
const EXPERIENCE_UI12={render,peopleView,bind,uxAreas11,personProfileDialog6,showDigest6,digestDestination6};
function experienceConfirmation12(title,text,action,after,label){confirmAction(title,text,action,label);el('confirmAction').onclick=()=>{const completed=act(()=>({value:action()}),'Hotovo.');if(completed)after(completed.value);};}
function difficultyUI12(){show(`<h2>Obtížnost hry</h2><p>Změna platí pro další týdny stejné firmy. Vyber tempo, které tě baví.</p><div class="experience-options12">${Object.entries(DIFFICULTIES).map(([key,d])=>`<article class="card"><h3>${esc(d.name)} ${key===state.difficulty?'· aktuální':''}</h3><p>${key==='relaxed'?'Více hostů a více času mezi problémy.':key==='expert'?'Menší poptávka, častější potíže a rychlejší konkurence.':'Vyvážené budování a konkurenční tlak.'}</p>${rows([['Poptávka',round(d.demand*100)+' %'],['Nová provozní událost','Každých '+d.eventEvery+' týdnů'],['Rozhodování expanze soupeřů','Každých '+d.rivalEvery*2+' týdnů']])}<button class="${key===state.difficulty?'soft':'primary'}" data-difficulty12="${key}" ${key===state.difficulty||state.over?'disabled':''}>${key===state.difficulty?'Hraješ tuto obtížnost':'Zvolit '+esc(d.name)}</button></article>`).join('')}</div><p class="sub">Expanze soupeře potřebuje jeho skutečné peníze a vhodné místo. Změna nepřidá kapitál ani majetek. Minulé týdny a aktuální smlouvy zůstávají.</p>`);on('[data-difficulty12]',b=>{const q=difficultyQuote12(b.dataset.difficulty12);experienceConfirmation12('Změnit obtížnost na '+DIFFICULTIES[q.level].name+'?', 'Platí pro další odehrané týdny. Firma bude pokračovat se stejnými penězi, lidmi a historií.',()=>setDifficulty12(q.level,q),difficultyUI12,'Změnit obtížnost');el('cancelAction').onclick=difficultyUI12;});}
uxAreas11=function(){EXPERIENCE_UI12.uxAreas11();const b=document.createElement('button');b.id='difficultyOpen12';b.className='soft';b.textContent='Obtížnost · '+DIFFICULTIES[state.difficulty].name;b.onclick=difficultyUI12;el('modalContent').querySelector('.ux-utilities11').prepend(b);};
function careerCard12(a){const p=a.person,c=p.career12,g=c?.goal,n=c?.notice;return `<article class="card"><h3>${esc(p.name)}</h3><p>${esc(a.label)} · ${esc(CHARACTER_TYPES6[p.character6.trait].name)}</p>${rows([['Spokojenost',number(p.satisfaction,1)+'/100'],['Vztah s firmou',number(p.character6.relationship,1)+'/100'],['Ambice',number(p.ambition,0)+'/100'],['Cíl',g?CAREER_FOCUS12[g.focus]+' · '+number(careerGoalValue12(p,g,a),1)+' / '+g.target:'První cíl po čtyřech týdnech zkušeností']])}${n?`<div class="warning"><strong>Chce odejít před T${n.due}</strong><p>${esc(n.reason)}. Zlepši spokojenost na 45 a vztah na 40, nebo připrav nástupce.</p></div>`:g?`<p class="sub">${g.status==='active'?'Cíl do T'+g.due:g.status==='fulfilled'?'Cíl splněn':'Termín cíle uplynul'}. Cíl není automaticky přijatý slib firmy.</p>`:''}<button class="soft" data-career-person12="${p.pid}">Rozvoj, mzda a nástupce</button></article>`;}
peopleView=function(){return `<section class="card"><h2>Kariéry a nástupnictví</h2><p>Konkrétní cíle a včasné varování před odchodem. Příprava nástupce jej sama nenajme.</p><button class="primary" id="careerDirectory12">Otevřít vedení a nástupce</button></section>`+EXPERIENCE_UI12.peopleView();};
function careerDirectory12(){show(`<h2>Vedení a nástupci</h2><div class="experience-options12">${staffAssignments().map(careerCard12).join('')||empty('Nejprve najmi vedoucího vlastního provozu.')}</div><h3>Plány předání a historie</h3>${state.experience12.succession.slice().reverse().map(x=>`<article class="news succession-news12"><div><strong>${esc(x.name)} · ${({preparing:'Příprava',ready:'Připraven',appointed:'Jmenován',unavailable:'Nedostupný',cancelled:'Zrušeno'})[x.status]}</strong><p>${esc(x.mentorName)} · ${x.samples.length}/4 skutečných týdnů · zaplaceno ${money(x.fee)}</p></div><button class="soft" data-succession-open12="${x.id}">Otevřít plán</button></article>`).join('')||empty('Zatím bez placeného předání.')}<h3>Odchody</h3>${state.experience12.departures.slice().reverse().map(x=>`<p>T${x.week} · ${esc(x.name)} · ${esc(x.reason)}</p>`).join('')||empty('Zatím bez zaznamenaného odchodu.')}`);on('[data-career-person12]',b=>careerPersonUI12(b.dataset.careerPerson12));on('[data-succession-open12]',b=>successionReportUI12(b.dataset.successionOpen12));}
function careerPersonUI12(pid){const a=staffAssignments().find(a=>a.person.pid===pid);if(!a){personProfileDialog6(pid);return;}const p=a.person,g=p.career12?.goal;show(`<h2>${esc(p.name)} · další kariéra</h2>${careerCard12(a).replace(/<button[^>]*data-career-person12[^>]*>[^<]*<\/button>/,'')}<div class="fields">${field('Chráněná rezerva / týdny',input('careerReserve12',3,1,8,1))}${field('Region pro povýšení',`<select id="careerCity12">${CITIES.filter(c=>!state.regions.some(r=>r.city===c.name)).map(c=>option(c.name,c.name,'Praha')).join('')}</select>`)}</div><div class="actions"><button class="primary" id="careerTrain12" ${!g||g.status!=='active'||g.focus==='region'?'disabled':''}>Prověřit školení cíle</button><button class="soft" id="careerRaise12">Prověřit vyšší mzdu</button><button class="soft" id="careerPromote12" ${a.kind==='region'?'disabled':''}>Prověřit povýšení</button><button class="soft" id="careerProfile12">Osobnost a paměť</button></div><h3>Připravit nástupce</h3><p>Placené předání ${money(18000)}, čtyři skutečné týdny s tímto vedoucím. Vybraný kandidát zůstává na trhu práce a může být přijat jinam; změna se pak projeví v plánu.</p>${field('Konkrétní kandidát',`<select id="successionPid12">${state.talents.filter(p=>!academyBusy6(p.pid)).map(p=>option(p.pid,p.name+' · '+p.skill+'/100','')).join('')}</select>`)}<button class="primary" id="successionPreview12" ${!state.talents.length?'disabled':''}>Prověřit přípravu nástupce</button><div class="actions"><button class="soft" id="careerBack12">Všichni vedoucí</button></div>`);el('careerBack12').onclick=careerDirectory12;el('careerProfile12').onclick=()=>personProfileDialog6(pid);for(const [id,action] of [['careerTrain12','training'],['careerRaise12','raise'],['careerPromote12','promote']])el(id).onclick=()=>{try{const city=el('careerCity12').value,reserve=Number(el('careerReserve12').value),q=careerActionQuote12(pid,action,city,reserve);show(`<h2>${esc(q.name)} · schválit krok</h2>${rows([['Krok',({training:'Školení cíle',raise:'Vyšší smluvní mzda',promote:'Povýšení do '+city})[action]],['Platba nyní',money(q.cost)],['Změna pravidelných nákladů',money(q.weekly)+'/týden'],['Chráněná hotovost',money(q.protectedCash)]])}<div class="actions"><button class="primary" id="careerConfirm12" ${!q.safe?'disabled':''}>Schválit krok</button><button class="soft" id="careerCancel12">Zrušit</button></div>`);el('careerCancel12').onclick=()=>careerPersonUI12(pid);el('careerConfirm12').onclick=()=>act(()=>{doCareerAction12(pid,action,city,reserve,q);careerPersonUI12(pid);});}catch(e){toast(e.message);}};el('successionPreview12').onclick=()=>{try{const selected=el('successionPid12').value,reserve=Number(el('careerReserve12').value),q=successionPlanQuote12(a.kind,a.id,selected,reserve);experienceConfirmation12('Připravit '+q.name+'?',money(q.fee)+' za čtyři doložené týdny předání. Nábor a mzda se hradí později. Chráněná hotovost '+money(q.protectedCash)+'.',()=>planSuccession12(a.kind,a.id,selected,reserve,q),x=>successionReportUI12(x.id),'Zaplatit přípravu');}catch(e){toast(e.message);}};}
function successionReportUI12(id){const x=state.experience12.succession.find(x=>x.id===id);if(!x)throw Error('Plán není dostupný.');const e=successionEntity12(x.kind,x.target);show(`<h2>${esc(x.name)} · nástupnictví</h2>${rows([['Mentor',x.mentorName],['Stav',({preparing:'Příprava',ready:'Připraven ke jmenování',appointed:'Jmenován',unavailable:'Nedostupný',cancelled:'Zrušeno'})[x.status]],['Zaplacený výcvik',money(x.fee)],['Doložené týdny',x.samples.length+' / 4'],['Dovednost',CAREER_FOCUS12[x.focus]],['Výchozí dovednost',number(x.before,0)]])}${x.status==='preparing'&&e?.manager?.pid!==x.mentor?'<div class="warning">Původní mentor už tento provoz nevede. Předání je pozastavené; můžeš je zrušit a připravit nový plán.</div>':''}<div class="table-scroll"><table><thead><tr><th>Týden</th><th>Před</th><th>Po skutečném výcviku</th></tr></thead><tbody>${x.samples.map(s=>`<tr><td>T${s.week}</td><td>${number(s.before,0)}</td><td>${number(s.after,0)}</td></tr>`).join('')}</tbody></table></div>${['ready','preparing'].includes(x.status)?`${field('Rezerva po jmenování / týdny',input('successionReserve12',3,1,8,1))}<button class="primary" id="successionAppoint12">${x.status==='ready'?'Prověřit nábor a jmenování':'Prověřit dřívější převzetí vedení'}</button>`:''}${['preparing','ready'].includes(x.status)?'<button class="quiet" id="successionCancel12">Zrušit další předání</button>':''}<button class="soft" id="successionBack12">Všichni vedoucí</button>`);el('successionBack12').onclick=careerDirectory12;if(el('successionCancel12'))el('successionCancel12').onclick=()=>{const stamp=leadershipStamp9();experienceConfirmation12('Zrušit další předání?', 'Zaplacený výcvik a již získané dovednosti zůstanou v historii. Nevzniká vrácení ani další platba.',()=>{if(stamp!==leadershipStamp9())throw Error('Firma se změnila.');x.status='cancelled';x.finished=state.week;},()=>successionReportUI12(id),'Zrušit předání');};if(el('successionAppoint12'))el('successionAppoint12').onclick=()=>{try{const reserve=Number(el('successionReserve12').value),q=successionAppointQuote12(id,reserve);experienceConfirmation12('Jmenovat '+q.name+'?', (x.samples.length<4?'Předání není dokončené ('+x.samples.length+'/4 týdnů). Kandidát převezme vedení se současnými dovednostmi. ':'')+'Nábor '+money(q.cost)+', změna týdenních závazků '+money(q.weekly)+', chráněná hotovost '+money(q.protectedCash)+'.',()=>appointSuccession12(id,reserve,q),()=>successionReportUI12(id),'Najmout a jmenovat');}catch(e){toast(e.message);}};}
personProfileDialog6=function(pid){EXPERIENCE_UI12.personProfileDialog6(pid);const a=staffAssignments().find(a=>a.person.pid===pid);if(a){const b=document.createElement('button');b.className='primary';b.id='careerProfileOpen12';b.textContent='Kariérní cíl, mzda a nástupnictví';b.onclick=()=>careerPersonUI12(pid);el('modalContent').querySelector('h2').after(b);}};
digestDestination6=function(x){if(x.key.startsWith('succession-')){closeDigest6();successionReportUI12(x.target);return;}if(x.key.startsWith('career-')){closeDigest6();careerPersonUI12(x.target);return;}return EXPERIENCE_UI12.digestDestination6(x);};
showDigest6=function(week){EXPERIENCE_UI12.showDigest6(week);const h=weeklyDigest6(week),root=el('modalContent');if(!h||!el('modal').open)return;const waiting=h.items.filter(x=>x.pending&&digestPending6(x)),section=document.createElement('section');section.id='weeklyRequests12';section.className='digest-section6';section.innerHTML=`<h3>Kdo čeká na tvoje rozhodnutí · ${waiting.length}</h3>${waiting.map(x=>`<article class="news digest-item6 ${x.severity===2?'digest-urgent6':''}"><div><strong>${esc(x.title)}</strong><p>${esc(x.text)}</p>${x.due!==null?'<small>Termín T'+x.due+'</small>':''}</div><button class="soft mini" data-weekly-request12="${esc(x.key)}" data-digest-open6="${esc(x.key)}">${digestActionLabel6(x)}</button></article>`).join('')||empty('Teď nikdo nečeká na tvé rozhodnutí. Události a výsledky tohoto týdne najdeš níže.')}`;root.querySelector('.digest-overview6').before(section);on('[data-weekly-request12]',b=>digestDestination6(h.items.find(x=>x.key===b.dataset.weeklyRequest12)));const keys=new Set(waiting.map(x=>x.key));for(const b of root.querySelectorAll('[data-digest-open6]'))if(!section.contains(b)&&keys.has(b.dataset.digestOpen6))b.closest('article').remove();for(const s of root.querySelectorAll('.digest-section6'))if(s!==section&&s.querySelector('article')===null&&s.querySelector('h3')?.textContent!=='Co se stalo')s.remove();for(const s of root.querySelectorAll('.digest-section6')){const heading=s.querySelector('h3');if(s!==section&&heading)heading.textContent=heading.textContent.replace(/ · [0-9]+$/, ' · '+s.querySelectorAll('article').length);}const events=document.createElement('h3');events.textContent='Co se stalo tento týden';root.querySelector('.digest-overview6').after(events);};
bind=function(){EXPERIENCE_UI12.bind();if(el('careerDirectory12'))el('careerDirectory12').onclick=careerDirectory12;};
render=function(...args){EXPERIENCE_UI12.render(...args);if(el('uxAll11'))el('uxAll11').onclick=uxAreas11;if(view==='crew'&&!gameMode6&&el('content')&&!el('crewCareers12')){const b=document.createElement('button');b.id='crewCareers12';b.className='soft';b.textContent='Vedení, kariéry a nástupci';b.onclick=careerDirectory12;el('content').prepend(b);}if(weekReportPending12.has(state)){const week=weekReportPending12.get(state);weekReportPending12.delete(state);if(weeklyDigest6(week))showDigest6(week);}};
render();
